// Package generator holds what every proxy's generator reads the same way: the input, the files a generator returns,
// the header line, and the rules that read the model alike for every proxy. It is not part of model, because Input
// names origins.File and rpc.Route, and origins and rpc import model.
package generator

import (
	"slices"
	"strings"

	"github.com/kitecorp/proxyfile/v2/internal/model"
	"github.com/kitecorp/proxyfile/v2/internal/origins"
	"github.com/kitecorp/proxyfile/v2/internal/rpc"
)

// Input is everything the generated file is made from.
type Input struct {
	Gateway *model.Gateway
	Origins *origins.File
	RPC     []rpc.Route // sorted by path; nil without an rpc entry
}

// File is one file a generator returns. Name "" is the configuration, written at -o; any other Name is a file the
// configuration loads, written under that fixed name in the folder of -o. That Name is a name alone, with no folder:
// render refuses any other as a bug, so no file is written outside the folder of -o.
type File struct {
	Name  string
	Bytes []byte
}

// Refused is the error of a generator that refuses a value of the input as it writes it, by the key that holds the
// value, as a target's declaration refuses a key: a value whose written form only the generator knows, such as one
// longer than the proxy reads once written. render reports its problems as the refusals they are, not as a bug in
// proxyfile.
type Refused struct{ Problems []model.Problem }

func (r Refused) Error() string {
	lines := make([]string, len(r.Problems))
	for i, problem := range r.Problems {
		lines[i] = problem.String()
	}
	return strings.Join(lines, "\n")
}

// Header is line 1 of every generated file. It names no input and no version, so the bytes depend on the model
// alone.
const Header = "# Generated by proxyfile. Do not edit: change the proxyfile beside it and run proxyfile render; " +
	"proxyfile check fails on a hand edit.\n"

// questionHeaders are the headers a route's question travels in, which the proxy sends to the check.
var questionHeaders = []model.Header{{Name: "x-gateway-action"}, {Name: "x-gateway-reports"}}

// RemovedFromClients is the early header removal's list, before the proxy's own unchecked mark: remove_from_clients in
// the order written, then, with auth.ask, the question headers and each accept name, then, with auth.jwt, each claims
// header, each that no entry before it covers. Only the gateway, the check and the token set those headers, so a
// client's copy is removed whether or not remove_from_clients lists it. A covered header adds nothing, so a file whose
// remove_from_clients covers them all gets no entry from here.
func RemovedFromClients(g *model.Gateway) []model.Header {
	var set []model.Header
	if g.Auth != nil {
		set = slices.Concat(questionHeaders, g.Auth.Accept)
	}
	if g.JWT != nil {
		for _, claim := range g.JWT.Claims {
			set = append(set, model.Header{Name: claim.Header})
		}
	}
	removed := slices.Clone(g.RemoveFromClients)
	for _, header := range set {
		if !slices.ContainsFunc(removed, func(entry model.Header) bool { return entry.Covers(header) }) {
			removed = append(removed, header)
		}
	}
	return removed
}

// LimitOf is the limit of one entry of routes: the rpc entry's or the route's own, nil without one.
func LimitOf(route *model.Route) *model.RateLimit {
	if route.RPC != nil {
		return route.RPC.RateLimit
	}
	return route.RateLimit
}

// BucketID names the bucket of one entry of routes: rpc for the rpc entry, the route's name otherwise. It is never the
// name of a route the proxy writes, which several rendered routes can share (an rpc entry's routes and a plain route
// may carry the same name), while the read rules keep each route's name unique and never rpc.
func BucketID(route *model.Route) string {
	if route.RPC != nil {
		return "rpc"
	}
	return route.Name.Value
}

// Bucket is one token bucket of a route's rate limit: MaxTokens is requests + burst, and TokensPerFill requests, which
// the proxy adds over each FillInterval, the period.
type Bucket struct {
	ID                       string
	ByClient                 bool
	MaxTokens, TokensPerFill int64
	FillInterval             string
}

// Buckets is one bucket for each limited entry of routes, in the written order.
func Buckets(g *model.Gateway) []Bucket {
	var list []Bucket
	for i := range g.Routes {
		if limit := LimitOf(&g.Routes[i]); limit != nil {
			list = append(list, Bucket{ID: BucketID(&g.Routes[i]), ByClient: limit.ByClient, MaxTokens: limit.Requests + limit.Burst,
				TokensPerFill: limit.Requests, FillInterval: model.FormatSeconds(limit.Per.Millis)})
		}
	}
	return list
}
